import type {ArticleSection,Branch,ReadingEntry,SourceLink} from '../types/philosophy';

const section=(id:string,title:string,paragraphs:string[],relatedBranchIds?:string[],relatedPhilosopherIds?:string[],relatedWorkTitles?:string[]):ArticleSection=>({id,title,paragraphs,relatedBranchIds,relatedPhilosopherIds,relatedWorkTitles});
const reading=(author:string,title:string,difficulty:ReadingEntry['difficulty'],whyRead:string,type:ReadingEntry['type']='primary'):ReadingEntry=>({author,title,difficulty,type,whyRead});
const source=(label:string,url:string,type:SourceLink['type'],notes?:string):SourceLink=>({label,url,type,notes});

export const marxismBranchArticle:ArticleSection[]=[
  section('contested-family','A contested family, not Marx repeated',[
    'Marxism is a family of intellectual traditions, political organizations, social movements, and state doctrines that claim some inheritance from Karl Marx. No single proposition unites every member. Some center class struggle and capitalist exploitation; some a materialist method; some revolutionary organization, public ownership, democratic planning, human emancipation, or critique of ideology. They disagree about value, historical laws, moral norms, the state, parties, markets, democracy, race, gender, colonialism, ecology, and even whether “Marxist” remains a useful name.',
    'Four questions should remain separate. What did Marx and Engels argue? How did later thinkers reconstruct that inheritance? How did organizations use it in strategy and internal discipline? What happened when parties claiming Marxism exercised state power? Intellectual genealogy cannot excuse political outcomes, while outcomes do not prove that every idea caused them. Marxism includes social democracy, communism, council traditions, critical theory, anticolonial liberation, Black radical thought, feminism, analytical reconstruction, ecology, and more. A responsible history studies crossings and exclusions without turning either Soviet Marxism-Leninism or academic Western theory into the whole tradition.'
  ],['political-philosophy','continental-philosophy'],['marx'],['Capital','The Communist Manifesto']),
  section('marx-engels','Marx, Engels, and the making of an inheritance',[
    'Marx and Engels were collaborators, not interchangeable authors. Engels brought experience of industry, independent work on political economy and nature, organizational labor, and decisive editorial support. Their jointly authored Manifesto and German Ideology manuscripts belong to a shared project, while Capital Volume I is Marx’s authored publication. After Marx’s death, Engels edited Volumes II and III from manuscripts, defended the tradition in political controversies, and supplied influential popular formulations of historical and dialectical materialism. Those labors made Marx available while also shaping what later readers understood as a system.',
    'Early “Marxism” was constructed through editions, summaries, party education, translations, and polemics before much of Marx’s corpus was available. The 1844 manuscripts and Grundrisse entered debate decades later; critical editions have since exposed layers of revision and editorial choice. Disputes about whether Engels naturalized or systematized Marx too strongly remain live, but a simple betrayal story is inadequate. Marx approved some of Engels’s expositions and depended on his collaboration, yet later orthodoxy often drew a closed worldview from texts Marx left open or unfinished. The history begins with mediation, not pure doctrine followed by corruption.'
  ],['political-philosophy','continental-philosophy'],['marx'],['Anti-Dühring','Capital']),
  section('second-international','The Second International and orthodox Marxism',[
    'After 1889, mass socialist parties and unions made Marxism a language of organized working-class politics, especially in Europe. Karl Kautsky, Georgi Plekhanov, August Bebel, and others systematized historical materialism, class politics, and expectations of capitalist development. Parliamentary growth coexisted with a revolutionary horizon: parties built newspapers, schools, cooperatives, unions, and electoral organizations while often describing socialism as the outcome of historical laws. This combination gave millions political education and institutional power, but it could turn strategy into waiting for an apparently inevitable future.',
    'The International was never uniform. National parties faced different states, suffrage rules, labor structures, empires, peasantries, and religious cultures. Many European socialists treated colonial rule as progressive or failed to oppose it consistently, while activists from colonized regions pressed different priorities. The collapse of international unity in 1914, when major parties backed their governments in world war, exposed the weakness of formal internationalism against national institutions and loyalties. Later communists, reformists, and antiwar socialists drew incompatible lessons from that failure.'
  ],['political-philosophy'],['marx'],['The Class Struggle','The Erfurt Program']),
  section('revisionism','Revisionism, reform, and the problem of transition',[
    'Eduard Bernstein argued that capitalism was adapting through credit, corporations, unions, and democracy rather than moving toward the predicted polarization and collapse. Socialists should state their ethical and democratic commitments openly and pursue reform instead of preserving revolutionary rhetoric. “Revisionism” became an accusation as well as a position. Orthodox opponents defended class antagonism and the need for systemic transformation, while reformist practice often expanded even where parties officially rejected Bernstein.',
    'The dispute cannot be reduced to timid reform versus courageous revolution. Reforms can improve lives, build capacities, and shift power; they can also stabilize capitalism, become reversible, or leave ownership untouched. Revolutionary expectation can reveal structural limits; it can also justify postponing democratic scrutiny until after a rupture. Later welfare states, social-democratic compromises, neoliberal reversals, and democratic-socialist projects repeatedly reopen the question. What changes accumulate toward a different mode of production, and what institutions prevent a transition conducted in the name of workers from escaping their control?'
  ],['political-philosophy'],['marx'],['Evolutionary Socialism','Reform or Revolution']),
  section('luxemburg','Rosa Luxemburg: accumulation, mass action, and democracy',[
    'Rosa Luxemburg joined economic analysis, internationalism, and revolutionary organization while resisting bureaucratic substitution for mass initiative. She debated Bernstein, analyzed imperial expansion and accumulation, supported mass strikes as schools of collective action, and opposed the First World War. Her arguments did not romanticize spontaneity as action without organization. They stressed a reciprocal process in which struggle educates organizations and organizations help struggles become durable.',
    'Luxemburg welcomed the Russian Revolution’s break with war and property while criticizing Bolshevik restrictions on elections, political freedom, and opposition. Her defense of public contestation rested on revolutionary grounds: democratic capacities develop through participation and error, not through commands issued for an allegedly mature future. Her own economic theory and strategic judgments remain disputed, and later traditions selectively claimed her. She nevertheless marks a permanent Marxist question: can emancipation be achieved by institutions that deny the self-activity through which emancipated people are supposed to rule?'
  ],['political-philosophy'],['marx'],['Reform or Revolution','The Accumulation of Capital','The Russian Revolution']),
  section('lenin','Lenin: imperialism, organization, and revolutionary rupture',[
    'Lenin adapted Marxism to autocratic Russia, underground organization, uneven capitalist development, empire, war, and peasant politics. What Is to Be Done? argues for a disciplined organization capable of sustaining political struggle beyond local economic demands, though debates continue over how its claims relate to later party practice. His theory of imperialism connects monopoly, finance, capital export, and rivalry among great powers. It shaped anticolonial Marxism even as scholars dispute its economic periodization and whether later forms of empire fit the model.',
    'In 1917 Lenin rejected a staged expectation that Russia must complete a long bourgeois phase before socialist action. The April Theses and State and Revolution link immediate rupture to soviet power and the destruction of a bureaucratic-military state apparatus. Yet governing amid war, collapse, foreign intervention, famine, and civil conflict produced centralization, coercion, and suppression. Historical emergency helps explain those choices without rendering them politically innocent or theoretically irrelevant. Leninism became both a strategy of organization and, after Lenin, a source selectively codified for state authority.'
  ],['political-philosophy'],['marx'],['What Is to Be Done?','Imperialism, the Highest Stage of Capitalism','State and Revolution']),
  section('russian-revolution','Revolution, civil war, and the consolidation of party power',[
    'The Russian Revolution joined mass participation, military breakdown, land seizure, worker organization, national movements, and competing socialist parties. Bolshevik leadership mattered, but October was not the execution of a philosophical blueprint. The new government withdrew from world war, redistributed land, and proclaimed worker rule while facing civil war and economic disintegration. It also dissolved the Constituent Assembly, restricted rival parties, expanded political policing, and subordinated independent institutions. Kronstadt, strikes, peasant rebellion, and factional conflict exposed the growing distance between rule in workers’ names and workers’ capacity to contest it.',
    'Marxists interpret this consolidation differently. Some emphasize unavoidable defense under catastrophic conditions, some organizational ideas that privileged the party, and some the emergence of new social interests within the state. The New Economic Policy later restored limited markets, showing that policy did not follow one linear doctrine. No single cause explains the outcome. Still, emergency institutions established precedents, personnel, and habits on which Stalinist rule could build. Treating every later crime as already contained in 1917 erases historical change; treating repression as an external accident erases institutional continuity and silenced alternatives.'
  ],['political-philosophy'],['marx'],['State and Revolution']),
  section('comintern-antifascism','The Communist International, anti-fascism, and discipline across borders',[
    'The Communist International sought to coordinate world revolution after 1919, linking parties across radically different political and colonial settings. It spread organizational training, labor strategy, and anticolonial networks, while increasingly subordinating national parties to decisions centered in Moscow. Debates over united fronts asked when communists should cooperate with social democrats and other forces. Ultra-left isolation and later popular-front alliances each carried costs as fascist movements destroyed labor organizations and democratic institutions.',
    'Communists became important organizers of anti-fascist resistance, unions, cultural work, and anticolonial struggle in many countries. They also defended changing Soviet policies, expelled dissenters, and sometimes treated loyalty to a foreign state as the measure of revolutionary correctness. The Nazi-Soviet pact produced a particularly severe crisis before the German invasion of the Soviet Union made wartime alliance and sacrifice central communist memories. This history shows how international solidarity, security, state interest, and party discipline can reinforce or corrupt one another rather than belonging to separate moral ledgers.'
  ],['political-philosophy'],['marx'],['Theses on the United Front']),
  section('soviet-orthodoxy','Soviet orthodoxy, modernization, and repression',[
    'Under Stalin, “Marxism-Leninism” became an official doctrine authorized by party and state. Forced collectivization and accelerated industrialization transformed property, agriculture, cities, education, and production at immense human cost. Political purges, executions, deportations, famine, labor camps, censorship, and the destruction of opposition were not marginal errors beside an otherwise intellectual history. They were exercises of concentrated state power justified through class categories, alleged historical necessity, security claims, and the party’s monopoly on truth. The defeat of Nazi Germany and expansion of education and industry are historically consequential, but they do not cancel victims or make terror an acceptable price formula.',
    'Soviet intellectual life was more complex than official manuals: philosophers, economists, scientists, writers, and dissidents worked within, around, and against changing constraints. Yet doctrine could be settled administratively, research subordinated to party lines, and disagreement criminalized. After Stalin, de-Stalinization, reform efforts, dissident Marxisms, national paths, and eventual stagnation changed the system without creating durable democratic socialism. The Soviet record belongs to evaluating Marxism because concepts, organizations, and authority interacted there. It is not the exhaustive meaning of Marxism, and it cannot be excluded merely by declaring the regime “not truly socialist.”'
  ],['political-philosophy'],['marx'],['Dialectical and Historical Materialism']),
  section('oppositions','Council, Trotskyist, and dissident communist alternatives',[
    'Communist traditions produced internal opponents of bureaucratic and one-party rule. Council communists emphasized workers’ councils and criticized both parliamentary substitution and centralized party government. Leon Trotsky analyzed uneven and combined development, defended permanent revolution, led the Left Opposition, and later described the Soviet Union as bureaucratically degenerated while retaining a defense of its nationalized property. Other dissidents understood the bureaucracy as a new ruling class or the system as state capitalist. These analyses disagreed about property, exploitation, international strategy, and whether reform remained possible.',
    'Opposition does not confer innocence. Trotsky participated in coercive civil-war policies; council strategies faced problems of coordination, defense, and institutional durability; dissident labels sometimes became sectarian identities. Their importance lies in showing that Marxist criticism of Soviet power was contemporary, not invented after collapse. Socialist legality, party pluralism, council democracy, union independence, and control of officials were contested from the beginning. Any claim that repression was simply demanded by Marxist theory must face these alternatives, and any claim that Marxism bears no responsibility must face their defeat by Marxist-led institutions.'
  ],['political-philosophy'],['marx'],['The Revolution Betrayed']),
  section('postwar-eurocommunism','Postwar communism, reform, and Eurocommunist paths',[
    'After 1945, communist parties governed across Eastern Europe under Soviet predominance and became powerful opposition or governing forces elsewhere. Anti-fascist prestige, land reform, industrialization, welfare provision, and expanded education coexisted with political policing, censorship, constrained sovereignty, and one-party rule. Uprisings and reform movements in East Germany, Hungary, Czechoslovakia, and Poland revealed recurring demands for worker power, national autonomy, civil freedom, and socialism without bureaucratic domination. Soviet military intervention made the limits of permitted reform unmistakable.',
    'Western parties pursued different paths. Italian, Spanish, and other Eurocommunists emphasized constitutional democracy, national strategy, pluralism, and distance from Moscow, often drawing on Gramsci. Communist municipal government, trade-union work, and anti-colonial solidarity produced real reforms even as parties lost industrial bases and electoral support. The collapse of European communist regimes in 1989–91 discredited official doctrines but did not settle whether democratic planning, workplace power, or public ownership were impossible. It changed the institutional world in which Marxist traditions had argued for a century.'
  ],['political-philosophy'],['marx'],['Prison Notebooks']),
  section('gramsci','Gramsci: hegemony, civil society, and political education',[
    'Antonio Gramsci asked why revolutionary crisis had not produced socialist transformation in Western Europe and why ruling orders secured active consent as well as coercion. “Hegemony” names intellectual, moral, and political leadership built across institutions and alliances, not merely media manipulation. Civil society—schools, churches, associations, newspapers, parties, and everyday practices—helps organize common sense. Economic power remains central, but it becomes politically effective through culture, organization, and state relations.',
    'Gramsci’s “war of position” addresses durable institutional struggle where a rapid assault on the state is insufficient. Organic intellectuals articulate experiences and organize collective understanding; a party can function as a modern prince that builds a new collective will. These ideas can support democratic coalition and education, yet they also raise the danger that leadership substitutes its interpretation for popular agency. The Prison Notebooks were written under fascist incarceration in coded, fragmentary form and later edited into thematic volumes. Their concepts should not be detached from textual history or turned into a neutral handbook for influencing opinion.'
  ],['continental-philosophy','political-philosophy'],['marx'],['Prison Notebooks']),
  section('western-marxism','Western Marxism, reification, and the turn toward culture',[
    '“Western Marxism” is a retrospective and contested label often applied to Lukács, Korsch, Gramsci, and later European theorists who renewed Hegelian, philosophical, cultural, and methodological dimensions of Marx. Lukács’s History and Class Consciousness analyzes reification: commodity relations organize not only exchange but perception, administration, and forms of knowledge. Class consciousness is not whatever workers happen to believe, which gives the theory critical power but creates a problem about who can speak for a class’s imputed standpoint.',
    'The tradition developed amid failed revolutions, fascism, Stalinism, exile, and the stabilization of capitalism. Its attention to culture, subjectivity, and philosophy was neither one flight from economics nor one coherent school. Benjamin’s historical materialism, Sartre’s attempted synthesis with existential freedom, Merleau-Ponty’s political phenomenology, Bloch’s philosophy of hope, and Althusser’s structural reconstruction conflict sharply. Critics argue that academic theory became detached from organization and political economy; defenders answer that capitalism’s reproduction through culture and subject formation required new objects. Both judgments fit some works better than others.'
  ],['continental-philosophy'],['marx','sartre','merleau-ponty'],['History and Class Consciousness']),
  section('frankfurt-school','The Frankfurt School: interdisciplinary critique after catastrophe',[
    'The Institute for Social Research joined Marxian political economy with sociology, psychology, philosophy, aesthetics, and empirical study. Horkheimer, Adorno, Marcuse, Benjamin, Fromm, and others confronted fascism, Stalinism, mass culture, antisemitism, exile, and advanced capitalism. Their “critical theory” asks how domination persists when direct economic interest does not explain compliance. Authoritarian personality, instrumental reason, culture industry, administered life, and one-dimensional society name different mechanisms, not a shared doctrine reducible to pessimism about popular entertainment.',
    'The Frankfurt tradition revises Marx by weakening confidence in historical progress and a single revolutionary subject. Habermas later reconstructs critique through communication, democratic legitimacy, and public reason, prompting objections that discourse theory moves too far from political economy. Feminist, critical-race, postcolonial, and contemporary critical theorists challenge the early school’s Eurocentrism, gender blindness, and limited account of colonialism while extending its interdisciplinary method. The tradition’s continuing problem is normative: how can critique diagnose distorted needs and consciousness without installing the theorist as an unquestionable authority over those being criticized?'
  ],['continental-philosophy','political-philosophy'],['marx','habermas'],['Traditional and Critical Theory','Dialectic of Enlightenment']),
  section('maoism-theory','Maoism: peasant revolution, contradiction, and the mass line',[
    'Chinese communists adapted Marxism-Leninism to a predominantly rural society shaped by imperial pressure, warlordism, Japanese invasion, civil war, peasant exploitation, and weak central authority. Mao Zedong treated peasants as a major revolutionary force, emphasized protracted people’s war, and described knowledge as developing through practical investigation. The “mass line” proposed gathering dispersed popular experience, synthesizing it through leadership, and returning it as policy. In principle it resists bookish doctrine; in practice it can make the party the final judge of what the masses truly meant.',
    'Mao’s essays on contradiction distinguish principal and secondary contradictions and insist that their configuration changes. His theory of continuing revolution under socialism challenged the idea that public ownership ended class conflict. Maoism later inspired movements across Asia, Africa, Latin America, Europe, and North America, often through anti-imperial and agrarian struggle. These adaptations differed greatly. Some built durable organizations among excluded rural populations; others reproduced militarism, personality cults, coercion, or simplified social analysis. “Maoism” therefore names both Chinese state doctrine and transnational strategies that cannot be evaluated as one event.'
  ],['political-philosophy'],['marx'],['On Contradiction','On Practice']),
  section('maoism-power','Maoist state power, mobilization, famine, and persecution',[
    'The People’s Republic transformed landholding, public health, literacy, industry, and national sovereignty. It also concentrated political authority in a party-state that punished opposition. The Great Leap Forward’s coercive collectivization, impossible production targets, distorted reporting, and grain policies contributed to catastrophic famine. The Cultural Revolution mobilized attacks on alleged capitalist restoration but produced persecution, factional violence, humiliation, imprisonment, educational rupture, and destruction of cultural life. These outcomes cannot be treated as rumors irrelevant to theory or balanced away by a ledger of achievements.',
    'Nor do they show that every Maoist concept has one inevitable consequence. War, international isolation, institutional inheritance, leader worship, bureaucratic incentives, and local conflict shaped events. Theoretical claims nevertheless mattered: voluntarist confidence, moralized class labels, campaigns against expertise, and authority to identify hidden enemies could disable correction. Later Chinese reforms retained one-party rule while introducing markets and private accumulation, further complicating the label “communist.” Evaluation should distinguish revolutionary independence, redistributive policies, Marxist arguments, Mao’s leadership, institutional mechanisms, and victims’ histories instead of collapsing them into praise or denunciation alone.'
  ],['political-philosophy'],['marx'],['On the Correct Handling of Contradictions Among the People']),
  section('anticolonial','Anti-colonial Marxism and national liberation',[
    'Marxism offered anticolonial thinkers a language for linking conquest, land, labor, extraction, class, and world markets. It also carried European stage theories and organizational models that required criticism. José Carlos Mariátegui treated Peruvian socialism as a creation rooted in Indigenous and agrarian realities rather than a copy. C. L. R. James connected the Haitian Revolution, Black self-emancipation, and international capitalism. Frantz Fanon joined political economy to racialized embodiment, colonial violence, national consciousness, and warnings about postcolonial elites. Amílcar Cabral analyzed class, culture, and national liberation without treating culture as timeless essence.',
    'Liberation movements faced a double problem: building unity against empire and preserving conflict and accountability within the future nation. Some Marxist-led movements achieved independence, land reform, education, or public provision; some produced centralized party-states, war economies, and repression. Cold War intervention and colonial legacies shaped these outcomes without explaining them away. Anti-colonial Marxism transformed the tradition by making empire constitutive rather than peripheral, but it never produced one formula for the relation among class, nation, ethnicity, peasantry, gender, culture, and democratic institutions.'
  ],['political-philosophy','continental-philosophy'],['marx','fanon'],['The Black Jacobins','The Wretched of the Earth']),
  section('dependency-world-systems','Dependency, unequal exchange, and world-systems analysis',[
    'Latin American, African, Caribbean, and other theorists challenged modernization stories in which every country advances through the same national stages. Dependency approaches argued that “underdevelopment” can be actively reproduced through colonial histories, trade structures, foreign ownership, debt, and alliances between external capital and domestic classes. André Gunder Frank, Ruy Mauro Marini, Samir Amin, and others disagreed over national bourgeoisies, super-exploitation, delinking, and possibilities for autonomous development. Their arguments turned the world market from a background into a structured relation of power.',
    'Immanuel Wallerstein’s world-systems analysis studies a capitalist world-economy organized through core, semiperipheral, and peripheral relations over long periods. Unequal-exchange theories ask how wage differences, productivity, monopoly, and trade distribute value internationally. Critics question state-centered categories, overly stable zones, economic functionalism, and insufficient attention to race, gender, ecology, and local agency. These debates matter because a politics framed only within one nation may redistribute domestically while relying on extraction and cheap labor elsewhere. Internationalism requires institutional analysis, not moral solidarity alone.'
  ],['political-philosophy'],['marx','fanon'],['Accumulation on a World Scale','The Modern World-System']),
  section('black-marxisms','Black Marxisms, racial capitalism, and the Black radical tradition',[
    'Black Marxist traditions analyze capitalism through slavery, colonialism, racialized labor, land, policing, and imperial war while challenging European class schemas. W. E. B. Du Bois’s Black Reconstruction places enslaved people’s self-emancipation and the “general strike” at the center of the Civil War era, and examines how racial status divided labor and defeated interracial democracy. Claudia Jones, Walter Rodney, Angela Davis, Stuart Hall, and many others develop different accounts of gender, empire, culture, prisons, and political organization. No single theory called Black Marxism contains them all.',
    'Cedric Robinson’s Black Marxism argues that capitalism developed within already racialized European orders and reconstructs a Black radical tradition not derived from Marxism. The concept of racial capitalism is now used in several, sometimes incompatible, ways. Some scholars integrate race into capitalist accumulation; some resist making capitalism the origin or exhaustive explanation of racial domination; some criticize Robinson’s history while retaining his challenge. The central correction is that race is not a decorative “identity” added after class analysis. Racial rule helps constitute property, labor markets, citizenship, coercion, and collective agency, while Black radical histories exceed any one European inheritance.'
  ],['political-philosophy','feminist-philosophy'],['marx','angela-davis'],['Black Reconstruction in America','Black Marxism','Women, Race & Class']),
  section('feminist-marxisms','Marxist feminism and social-reproduction theory',[
    'Marxist feminists ask how gendered labor, households, sexuality, law, violence, and care reproduce capitalist society and how class institutions reproduce gender. Engels’s Origin of the Family offered an influential historical connection among property, family, and women’s subordination, but its anthropology and linear stages are contested. Later debates include domestic-labor theory, wages for housework, dual-systems approaches, materialist feminism, and unitary theories. Each defines production, patriarchy, value, and political subjects differently.',
    'Social-reproduction theory studies how labor-power and life are sustained through households, schools, health systems, migration, communities, and state provision. Much of this necessary work is unpaid or underpaid and distributed through race, citizenship, disability, and global care chains. Feminist theorists also criticize productivism and a model of emancipation centered on entry into wage labor. Black, anticolonial, queer, and Indigenous feminisms show that family and reproduction cannot be understood through a universal household. These traditions extend Marx’s account of social reproduction while correcting exclusions his own analysis did not overcome.'
  ],['feminist-philosophy','political-philosophy'],['marx','angela-davis','beauvoir'],['The Origin of the Family, Private Property and the State','Women, Race & Class']),
  section('humanism-structuralism','Humanism, structural Marxism, and the subject of history',[
    'Twentieth-century Marxist humanists recovered the 1844 manuscripts to emphasize alienation, praxis, dignity, and democratic self-emancipation against Stalinist objectivism. Henri Lefebvre examined everyday life; Erich Fromm connected social character and human needs; Raya Dunayevskaya linked humanism to revolution, race, gender, and anticolonial struggle. In Eastern Europe, Praxis philosophers and dissidents used Marx against bureaucratic rule. Critics replied that appeals to a universal human essence could ignore how subjects are historically produced.',
    'Louis Althusser’s structural Marxism proposed an epistemological break between the early humanist Marx and the mature science of social formations. Structural causality, overdetermination, ideological state apparatuses, and reproduction displaced a sovereign subject of history. Althusser helped readers reject simple base-superstructure causation and attend to institutions, but his scientific rhetoric and antihumanism created new problems of agency and normative judgment. Later theorists combine or reject these positions. The dispute asks whether emancipation needs an account of human flourishing, whether that account can avoid essentialism, and how structured agents can transform the relations that form them.'
  ],['continental-philosophy','political-philosophy'],['marx'],['Marxism and Humanism','For Marx']),
  section('autonomism','Operaismo, autonomism, and struggles inside production',[
    'Italian operaismo, or workerism, reversed a passive picture in which workers merely respond to capital’s development. Inquiry into factories, refusal of work, sabotage, migration, and new workforce composition treated workers’ struggles as forces that compel capitalist reorganization. Tronti’s “reversal of perspective” and later autonomist concepts of social factory, immaterial labor, multitude, and cognitive capitalism shifted attention from official parties toward dispersed antagonism and changing forms of cooperation.',
    'This tradition influenced feminist wages-for-housework campaigns and analyses of unwaged labor, while internal disagreements remain substantial. Critics argue that celebrations of refusal, autonomy, or networked production can understate institutions, durable organization, racial and gender hierarchy, and capital’s continuing command. Claims that knowledge work has displaced industrial labor can erase mines, farms, warehouses, care work, and global manufacturing. The lasting contribution is methodological: investigate how workers and communities resist within changing labor processes rather than deriving political subjects from an abstract map of the economy.'
  ],['political-philosophy','feminist-philosophy'],['marx'],['Workers and Capital']),
  section('analytical-marxism','Analytical Marxism: clarity, mechanisms, and normative reconstruction',[
    'Analytical Marxism emerged in the late 1970s among philosophers and social scientists seeking clear arguments, explicit mechanisms, and dialogue with mainstream methods. G. A. Cohen reconstructed historical materialism through functional explanation; John Roemer modeled exploitation without relying on every element of labor-value theory; Jon Elster criticized loose dialectical claims; Adam Przeworski studied class strategy and electoral choices. The group rejected the idea that obscurity or invocation of totality could replace explanation.',
    'Its members did not agree on methodological individualism, rational choice, history, exploitation, or socialism. As confidence in an inevitable transition declined, normative questions became more explicit. Cohen moved toward egalitarian political philosophy and criticized market incentives; Erik Olin Wright combined class analysis with institutional “real utopias.” Critics argue that analytical methods strip Marxism of dialectic, history, and emergent social relations. Defenders answer that any theory of structures still owes an account of mechanisms and evidence. The movement shows a Marxism willing to abandon substantive Marxian claims while retaining socialist equality and analysis of class power.'
  ],['analytic-philosophy','political-philosophy'],['marx','rawls'],['Karl Marx’s Theory of History','Making Sense of Marx']),
  section('ecological-marxisms','Ecological Marxism, metabolism, and ecosocialism',[
    'Ecological Marxists analyze how competitive accumulation organizes energy, extraction, agriculture, waste, and unequal exposure to environmental harm. “Metabolic rift” theories develop Marx’s account of disruptions in exchanges between society and the rest of nature, especially the separation of town and country and depletion of soil. James O’Connor’s “second contradiction” emphasizes how capital undermines its own conditions of production. World-ecology approaches criticize a society-nature dualism and examine capitalism as a way of organizing nature, labor, and power together.',
    'Ecosocialism joins democratic control of production to ecological limits and just transition. Disputes concern growth, technology, planning, Indigenous sovereignty, population, imperial extraction, and whether Marx was productivist or moved toward a late ecological and even degrowth position. Soviet industrial damage and resource-intensive socialist modernization show that public ownership alone does not secure ecological rationality. Contemporary theory must explain how information, participation, restraint, and global responsibility work institutionally. Marxian critique identifies accumulation’s pressures; it does not provide an automatic environmental constitution.'
  ],['political-philosophy','ethics'],['marx'],['Capital']),
  section('political-economy','Value, crisis, dependency, and changing capitalism',[
    'Marxist political economy divides over the meaning of value, prices, profit, crisis, and transformation. Orthodox labor-value, value-form, monetary, temporal single-system, Sraffian, regulation, social-structure-of-accumulation, and autonomist approaches disagree about basic categories. Some treat the tendency of the profit rate to fall as central; others emphasize realization, financial instability, class conflict, or institutional regimes. “Marxian economics” can name research inspired by Marx without acceptance of a complete Marxist politics.',
    'Global debates add imperialism, dependency, unequal exchange, world-systems, and development. Dependency thinkers challenged the promise that peripheral societies would repeat a metropolitan path, while world-systems analysis shifted attention to core, periphery, and long historical cycles. Critics ask whether these frameworks understate domestic class relations, state projects, race, gender, or the agency of peripheral workers. Financialization, logistics, platform firms, intellectual property, global supply chains, and informal labor require new empirical study. Repeating nineteenth-century categories without mediation is no more Marxist than assuming capitalism has become entirely new.'
  ],['political-philosophy'],['marx'],['Capital','Monopoly Capital']),
  section('democracy-organization','Parties, councils, movements, and socialist democracy',[
    'Marxist politics has organized through mass parties, vanguard parties, unions, councils, guerrilla armies, national-liberation fronts, cooperatives, tenants’ groups, and decentralized movements. Each form solves some problems and creates others. Parties can coordinate long projects and contest state power but accumulate bureaucratic interests. Councils can enable workplace participation yet struggle with scale, continuity, and inclusion beyond employment. Movements can multiply initiative while lacking durable decision procedures. No organizational form guarantees that leaders remain accountable or that marginalized members gain voice.',
    'Democratic Marxists argue that civil liberties, competitive politics, workplace democracy, and constitutional limits are parts of emancipation rather than bourgeois decorations. Leninist and revolutionary traditions reply that existing states and ownership structures constrain formally open competition. Historical experience makes both claims unavoidable: concentrated private power can hollow out democracy, and concentrated socialist state power can destroy it. A credible contemporary socialism must specify rights, opposition, independent associations, information, recall, courts, decentralization, expertise, emergency limits, and the relation between planning and markets before invoking a future withering away of the state.'
  ],['political-philosophy'],['marx'],['The Civil War in France']),
  section('culture-ideology','Culture, ideology, knowledge, and everyday life',[
    'Marxist cultural theory rejects the idea that art, media, religion, science, and philosophy merely mirror an economic base. Gramsci analyzes common sense and hegemony; Lukács reification and form; Benjamin technology, memory, and history; the Frankfurt School mass culture and instrumental reason; Raymond Williams cultural materialism; Stuart Hall articulation and encoding; Fredric Jameson the political unconscious. These approaches disagree about autonomy, realism, modernism, popular culture, and whether critique should recover emancipatory possibilities or diagnose incorporation.',
    'Ideology remains especially disputed. It can mean false or distorted belief, a worldview attached to a class, institutional practices that reproduce subjects, or objective appearances generated by social forms. Treating audiences as dupes grants the critic too much authority; treating all interpretation as equally situated can weaken explanation of domination. Marxist epistemology must also examine its own institutions, funding, parties, canons, and exclusions. A theory that explains every disagreement as class interest protects itself from correction. Reflexive criticism is therefore not optional: emancipatory knowledge must remain answerable to evidence and those whose lives it interprets.'
  ],['continental-philosophy','aesthetics','political-philosophy'],['marx'],['Prison Notebooks','Dialectic of Enlightenment']),
  section('religion-liberation','Religion, political theology, and liberation',[
    'Marx’s critique of religion is often reduced to one metaphor about opium. The surrounding argument treats religion as both an expression of suffering and a protest against it, while insisting that criticism must address the social conditions requiring consolation. Later Marxists vary from militant atheism and state suppression of religious institutions to alliances with believers and analyses of religion as culture, organization, hope, or ideology. Bloch recovers utopian surplus in religious traditions; Benjamin joins messianic motifs to historical materialism in a deliberately unstable form.',
    'Latin American liberation theology and related movements use Marxian social analysis within Christian commitments to the poor, base communities, and opposition to dictatorship and dependency. Black, Jewish, Islamic, Dalit, and other liberation currents create different encounters that cannot be grouped as one Marxist theology. Critics warn that class analysis can instrumentalize faith or ignore doctrine, while religious institutions can preserve patriarchy and hierarchy. These crossings show that secularization is not a universal prerequisite for emancipatory politics and that materialist criticism must study what religious practice actually does in a historical struggle.'
  ],['philosophy-of-religion','political-philosophy'],['marx'],['A Contribution to the Critique of Hegel’s Philosophy of Right']),
  section('contemporary','Contemporary work, technology, care, and crisis',[
    'Contemporary Marxist analysis studies insecure employment, global production networks, logistics, migration, debt, housing, finance, automation, and digital platforms. Platform firms can own infrastructure, data, and access while classifying workers as independent; algorithmic management renews old struggles over pace and surveillance. Yet not every user is a worker, not every datum creates value in the same sense, and “digital feudalism” may obscure continuing capitalist ownership and competition. Empirical distinctions matter more than attaching a new object to familiar vocabulary.',
    'Care crises and climate change also test priorities. A society can accumulate profitable assets while hospitals, schools, households, ecosystems, and public infrastructure deteriorate. Social-reproduction and ecological approaches show that waged production depends on activities and natural processes it does not adequately sustain. Anti-racist and abolitionist Marxists analyze policing, prisons, borders, and racialized dispossession alongside employment. Contemporary debates ask whether class can unify these struggles without reducing them, and whether Green New Deals, public ownership, cooperatives, planning, universal services, or degrowth can build transitions that are both effective and democratic.'
  ],['political-philosophy','feminist-philosophy','ethics'],['marx','angela-davis'],['Capital']),
  section('evaluation','How to evaluate a Marxist claim or project',[
    'Begin by identifying the kind of claim. Is it textual interpretation of Marx, an explanation of capitalism, a moral argument, an organizational strategy, a state policy, or a retrospective defense of an outcome? Evidence appropriate to one cannot settle the others. Then identify the bearer of power: workers, a party, a ministry, a movement, a racialized or gendered group, a nation, or “history” personified. Claims made in the name of a class must explain how actual members participate, disagree, and remove leaders.',
    'Next ask what the theory illuminates and what it treats as derivative. Does class analysis explain racial, colonial, gendered, ecological, and political relations, or merely rename them? Does a crisis tendency establish probability, possibility, or inevitability? Do public ownership and planning include accountable institutions? Finally compare intended emancipation with historical mechanisms and outcomes. Anti-communist polemic can erase labor victories, anticolonial liberation, welfare institutions, and genuine ideals; apologetic Marxism can erase famine, camps, censorship, invasion, and victims. Critical inheritance requires refusing both erasures.'
  ],['political-philosophy','ethics'],['marx'],['Capital']),
  section('what-counts','What counts as Marxist?',[
    'There is no neutral border police for the tradition. Textual fidelity may require retaining Marx’s categories; political fidelity may mean revising them to pursue self-emancipation under new conditions. Some communists deny social democrats the name; some humanists deny official Soviet orthodoxy; some analytical Marxists reject dialectics; some Black and feminist theorists inhabit Marxism critically; some scholars prefer “Marxian” for analysis without a political identity. Historical importance cannot be removed by declaring an unwelcome branch counterfeit.',
    'Useful questions replace a single essence. Which Marxian problem is retained: exploitation, alienation, historical materialism, value, class struggle, ideology, or associated production? Which later inheritance supplies party, state, culture, nation, race, gender, or ecology? What evidence could revise the position? What institutions embody its emancipatory claims? A tradition remains alive through argument, but pluralism is not immunity from judgment. Marxist projects can be more or less accurate, democratic, inclusive, and emancipatory; some have been catastrophically oppressive. Diversity makes evaluation more precise, not impossible.',
    'Boundaries are also relational. Marxists learned from and argued with anarchism about state and authority, liberalism about rights and pluralism, social democracy about reform, nationalism about collective self-determination, feminism about production and reproduction, and postcolonial theory about empire and Eurocentrism. Borrowing does not dissolve every difference. It reveals that traditions develop through criticism and shared struggles rather than sealed ownership of concepts. These exchanges can expose assumptions that internal debate has normalized. A self-described Marxism that cannot say what these encounters changed is offering an identity, not yet an adequate history.'
  ],['political-philosophy','continental-philosophy'],['marx'],['The Communist Manifesto']),
  section('reading-path','A staged path through Marxism’s arguments and histories',[
    'Begin by reading Marx separately: the Theses on Feuerbach, Manifesto, Eighteenth Brumaire, selections from Capital, Civil War in France, and Gotha critique, with attention to genre and date. Add Engels’s Socialism: Utopian and Scientific while asking what systematization changes. Then compare Bernstein and Luxemburg on reform, Lenin on organization, imperialism, and the state, and Gramsci on hegemony. Read historical scholarship on the Second International, Russian Revolution, Soviet Union, Chinese Revolution, and global communism beside participants’ texts.',
    'Follow several twentieth-century routes rather than one ladder. For Western and critical theory, sample Lukács, Horkheimer, Adorno, Benjamin, and Marcuse. For anticolonial and Black traditions, read James, Du Bois, Fanon, Cabral, Rodney, Davis, and Robinson. For feminism and social reproduction, compare domestic-labor, dual-systems, and unitary approaches. Add Althusser and Marxist humanists, Cohen and analytical critics, dependency and world-systems theory, and ecological Marxism. At every stage ask what is inherited from Marx, what historical problem prompts the revision, what organization or state is involved, and what outcomes test the claim.'
  ],['political-philosophy','continental-philosophy','feminist-philosophy'],['marx','fanon','angela-davis'],['Capital','Reform or Revolution','Prison Notebooks','Black Marxism'])
];

